/**
 * Original UI & design: Gustavo Fior (@gustavo-fior), Abdul Haidar & Foglamp Labs.
 * Extracted from https://github.com/foglamp-labs/foglamp — Apache-2.0.
 */
import type { Span, SpanStatus, Trace, Usage } from "./wire";

/** Per-trace totals, summed at finalize. `costUsd` is null when unpriced. */
export interface HudTotals {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  durationMs: number;
  /** Priced server-side via @foglamp/cost; null when the model is unknown. */
  costUsd: number | null;
}

interface Base {
  /** Epoch ms when the event was emitted. */
  ts: number;
  /** The top-level call id (one trace). */
  traceId: string;
}

/**
 * A live execution event. Discriminated by `type`. The HUD maintains an
 * in-memory model keyed by `traceId` and folds these in as they arrive; a
 * client that connects mid-run is replayed the broker's recent buffer first.
 */
export type HudEvent =
  | (Base & {
      type: "trace.start";
      /** Display label (traceName ?? agentName ?? operation). */
      name: string;
      agentName?: string;
      traceName?: string;
      workflowName?: string;
      workflowRunId?: string;
      sessionId?: string;
      provider?: string;
      model?: string;
      /** JSON catalog of tools offered to the model, if known at start. */
      toolCatalog?: string;
    })
  | (Base & { type: "step.start"; stepNumber: number; provider?: string; model?: string })
  | (Base & { type: "step.firstToken"; stepNumber: number; ttftMs?: number })
  | (Base & {
      type: "step.tokens";
      stepNumber: number;
      /** Cumulative output tokens so far this step. */
      outputTokens: number;
      /** Cumulative reasoning tokens so far (reasoning models). */
      reasoningTokens?: number;
      /** Instantaneous output tokens/sec, if derivable. */
      tps?: number;
    })
  | (Base & { type: "tool.start"; toolCallId: string; toolName: string; input?: string })
  | (Base & {
      type: "tool.end";
      toolCallId: string;
      toolName: string;
      status: SpanStatus;
      output?: string;
      errorMessage?: string;
      durationMs?: number;
    })
  | (Base & {
      type: "step.end";
      stepNumber: number;
      status: SpanStatus;
      usage?: Usage;
      ttftMs?: number;
      durationMs?: number;
      outputTps?: number;
      modelCallMs?: number;
    })
  | (Base & {
      type: "trace.end";
      status: SpanStatus;
      /** The fully-assembled trace (same shape the dashboard renders). */
      trace: Trace;
      totals: HudTotals;
    });

export type HudEventType = HudEvent["type"];

/** Sum a finalized trace's spans into HUD totals (cost filled in by the caller). */
export function totalsFromSpans(spans: Span[], costUsd: number | null): HudTotals {
  let inputTokens = 0;
  let outputTokens = 0;
  let totalTokens = 0;
  let minStart = Number.POSITIVE_INFINITY;
  let maxEnd = 0;
  for (const s of spans) {
    inputTokens += s.usage?.inputTokens ?? 0;
    outputTokens += s.usage?.outputTokens ?? 0;
    totalTokens += s.usage?.totalTokens ?? 0;
    if (s.startTime < minStart) minStart = s.startTime;
    if (s.endTime > maxEnd) maxEnd = s.endTime;
  }
  const durationMs = Number.isFinite(minStart) ? Math.max(0, maxEnd - minStart) : 0;
  return { inputTokens, outputTokens, totalTokens, durationMs, costUsd };
}

/**
 * Original UI & design: Gustavo Fior (@gustavo-fior), Abdul Haidar & Foglamp Labs.
 * Extracted from https://github.com/foglamp-labs/foglamp — Apache-2.0.
 */
export type Metadata = Record<string, string>;

export interface Customer {
  id: string;
  name?: string;
  imageUrl?: string;
}

export type SpanType = "agent" | "llm" | "tool" | "embedding" | "other";
export type SpanStatus = "ok" | "error" | "aborted";

export interface Usage {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
  reasoningTokens?: number;
  cachedInputTokens?: number;
  cacheWriteInputTokens?: number;
  imageCount?: number;
  webSearchCount?: number;
  requestCount?: number;
}

export interface Span {
  spanId: string;
  parentSpanId?: string;
  spanType: SpanType;
  name: string;
  /** Epoch milliseconds. */
  startTime: number;
  endTime: number;
  status: SpanStatus;
  errorMessage?: string;
  provider?: string;
  modelId?: string;
  usage?: Usage;
  ttftMs?: number;
  /** Total wall-clock ms spent inside reasoning blocks for this step. */
  reasoningDurationMs?: number;
  input?: string;
  output?: string;
  /** JSON catalog of tools offered to the model (name → {description, params}). */
  toolCatalog?: string;
  /** The system prompt / agent instructions for the run (root agent span only). */
  systemPrompt?: string;
  /** Pure model-call wall-clock for the step (ms), excluding tool execution. v7 only. */
  modelCallMs?: number;
  /**
   * Official provider response time (ms) from the AI SDK step `performance`
   * object: time spent waiting for the language-model response. Also feeds
   * `modelCallMs` (preferred over the derived value). v7 beta/canary only; absent on
   * v4–v6 wrap and older v7.
   */
  responseTimeMs?: number;
  /** Effective output tokens/sec over the full response (outputTokens/requestSeconds). v7 beta/canary only. */
  effectiveOutputTps?: number;
  /** Effective (input+output) tokens/sec over the full response. v7 beta/canary only. */
  effectiveTotalTps?: number;
  /** Output tokens/sec after the first output chunk; streaming steps only. v7 beta/canary only. */
  outputTps?: number;
  /** Input tokens/sec before the first output chunk (prefill rate); streaming steps only. v7 beta/canary only. */
  inputTps?: number;
  /**
   * Inter-output-chunk gap statistics (ms) from `performance`; present only for
   * streaming steps with ≥2 output chunks. v7 beta/canary only.
   */
  chunkJitter?: {
    min: number;
    p10: number;
    median: number;
    avg: number;
    p90: number;
    max: number;
  };
  /** OpenAI-style model build fingerprint (drift detection). */
  systemFingerprint?: string;
  /** JSON blob of provider safety ratings, as reported (no logprobs). */
  safetyMetadata?: string;
  /** JSON array of RAG/grounding citations (StepResult.sources); output-capture gated. */
  sources?: string;
  /** Rate-limit headroom, normalized cross-provider from response headers. */
  rateLimit?: {
    requestsLimit?: number;
    requestsRemaining?: number;
    requestsResetMs?: number;
    tokensLimit?: number;
    tokensRemaining?: number;
    tokensResetMs?: number;
  };
  metadata?: Metadata;
}

export interface Trace {
  traceId: string;
  traceName?: string;
  agentName?: string;
  workflowName?: string;
  workflowRunId?: string;
  sessionId?: string;
  customer?: Customer;
  metadata?: Metadata;
  spans: Span[];
}

export interface IngestPayload {
  version: "v1";
  traces: Trace[];
}
